package com.inventra.backend.model;
import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document; import java.time.LocalDateTime;
@Document(collection="stock_reservations") public class StockReservation { @Id private String id; private String orderId; private String warehouseId; private String productId; private int quantity; private ReservationStatus status=ReservationStatus.ACTIVE; private LocalDateTime createdAt=LocalDateTime.now(); private LocalDateTime releasedAt; public StockReservation(){} public String getId(){return id;} public void setId(String v){id=v;} public String getOrderId(){return orderId;} public void setOrderId(String v){orderId=v;} public String getWarehouseId(){return warehouseId;} public void setWarehouseId(String v){warehouseId=v;} public String getProductId(){return productId;} public void setProductId(String v){productId=v;} public int getQuantity(){return quantity;} public void setQuantity(int v){quantity=v;} public ReservationStatus getStatus(){return status;} public void setStatus(ReservationStatus v){status=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} public LocalDateTime getReleasedAt(){return releasedAt;} public void setReleasedAt(LocalDateTime v){releasedAt=v;} }
